o.a='\n## \ud83d\udcda \u5de5\u5177\u8be6\u7ec6\u6587\u6863\n\n### \u2699\ufe0f \u5b57\u6bb5\u8fc7\u6ee4\u673a\u5236\uff08\u51cf\u5c11 Token \u6d88\u8017\uff09\n\n**\u6240\u6709\u8fd4\u56de\u6570\u636e\u7684\u63d2\u4ef6\u65b9\u6cd5**\u90fd\u652f\u6301\u4ee5\u4e0b\u53ef\u9009\u53c2\u6570\u6765\u4f18\u5316\u8fd4\u56de\u7684\u6570\u636e\u91cf\uff1a\n\n#### \u53c2\u6570\u8bf4\u660e\n\n1. **mode** (\u5b57\u7b26\u4e32): \u6570\u636e\u6a21\u5f0f\n   - `"summary"` \u6216 `"s"`: \u4ec5\u8fd4\u56de\u7edf\u8ba1\u6570\u636e\uff08\u63a8\u8350\uff1a\u6700\u7701 Token\uff09\n   - `"compact"` \u6216 `"c"`: \u8fd4\u56de\u7b80\u5316\u5b57\u6bb5\u7684\u8bb0\u5f55\u5217\u8868\uff08\u5e73\u8861\uff09\n   - `"full"` \u6216 `"f"`: \u8fd4\u56de\u5b8c\u6574\u6570\u636e\uff08\u9ed8\u8ba4\uff09\n\n2. **fields** (\u6570\u7ec4): \u76f4\u63a5\u6307\u5b9a\u8fd4\u56de\u5b57\u6bb5\uff08\u4f18\u5148\u7ea7\u9ad8\u4e8e mode\uff09\n'
o.a='\n## \ud83d\udcda \u5de5\u5177\u8be6\u7ec6\u6587\u6863\n\n### \u2699\ufe0f \u5b57\u6bb5\u8fc7\u6ee4\u673a\u5236\uff08\u51cf\u5c11 Token \u6d88\u8017\uff09\n\n**\u6240\u6709\u8fd4\u56de\u6570\u636e\u7684\u63d2\u4ef6\u65b9\u6cd5**\u90fd\u652f\u6301\u4ee5\u4e0b\u53ef\u9009\u53c2\u6570\u6765\u4f18\u5316\u8fd4\u56de\u7684\u6570\u636e\u91cf\uff1a\n\n#### \u53c2\u6570\u8bf4\u660e\n\n1. **mode** (\u5b57\u7b26\u4e32): \u6570\u636e\u6a21\u5f0f\n   - `"summary"` \u6216 `"s"`: \u4ec5\u8fd4\u56de\u7edf\u8ba1\u6570\u636e\uff08\u63a8\u8350\uff1a\u6700\u7701 Token\uff09\n   - `"compact"` \u6216 `"c"`: \u8fd4\u56de\u7b80\u5316\u5b57\u6bb5\u7684\u8bb0\u5f55\u5217\u8868\uff08\u5e73\u8861\uff09\n   - `"full"` \u6216 `"f"`: \u8fd4\u56de\u5b8c\u6574\u6570\u636e\uff08\u9ed8\u8ba4\uff09\n\n2. **fields** (\u6570\u7ec4): \u76f4\u63a5\u6307\u5b9a\u8fd4\u56de\u5b57\u6bb5\uff08\u4f18\u5148\u7ea7\u9ad8\u4e8e mode\uff09\n   - \u793a\u4f8b: `fields: ["id", "title", "start", "end"]`\n'
o.a='\n## \ud83d\udcda \u5de5\u5177\u8be6\u7ec6\u6587\u6863\n\n### \u2699\ufe0f \u5b57\u6bb5\u8fc7\u6ee4\u673a\u5236\uff08\u51cf\u5c11 Token \u6d88\u8017\uff09\n\n**\u6240\u6709\u8fd4\u56de\u6570\u636e\u7684\u63d2\u4ef6\u65b9\u6cd5**\u90fd\u652f\u6301\u4ee5\u4e0b\u53ef\u9009\u53c2\u6570\u6765\u4f18\u5316\u8fd4\u56de\u7684\u6570\u636e\u91cf\uff1a\n\n#### \u53c2\u6570\u8bf4\u660e\n\n1. **mode** (\u5b57\u7b26\u4e32): \u6570\u636e\u6a21\u5f0f\n   - `"summary"` \u6216 `"s"`: \u4ec5\u8fd4\u56de\u7edf\u8ba1\u6570\u636e\uff08\u63a8\u8350\uff1a\u6700\u7701 Token\uff09\n   - `"compact"` \u6216 `"c"`: \u8fd4\u56de\u7b80\u5316\u5b57\u6bb5\u7684\u8bb0\u5f55\u5217\u8868\uff08\u5e73\u8861\uff09\n   - `"full"` \u6216 `"f"`: \u8fd4\u56de\u5b8c\u6574\u6570\u636e\uff08\u9ed8\u8ba4\uff09\n\n2. **fields** (\u6570\u7ec4): \u76f4\u63a5\u6307\u5b9a\u8fd4\u56de\u5b57\u6bb5\uff08\u4f18\u5148\u7ea7\u9ad8\u4e8e mode\uff09\n   - \u793a\u4f8b: `fields: ["id", "title", "start", "end"]`\n   - \u53ea\u8fd4\u56de\u6307\u5b9a\u5b57\u6bb5\uff0c\u5176\u4ed6\u5b57\u6bb5\u5ffd\u7565\n\n'
o.a='\n## \ud83d\udcda \u5de5\u5177\u8be6\u7ec6\u6587\u6863\n\n### \u2699\ufe0f \u5b57\u6bb5\u8fc7\u6ee4\u673a\u5236\uff08\u51cf\u5c11 Token \u6d88\u8017\uff09\n\n**\u6240\u6709\u8fd4\u56de\u6570\u636e\u7684\u63d2\u4ef6\u65b9\u6cd5**\u90fd\u652f\u6301\u4ee5\u4e0b\u53ef\u9009\u53c2\u6570\u6765\u4f18\u5316\u8fd4\u56de\u7684\u6570\u636e\u91cf\uff1a\n\n#### \u53c2\u6570\u8bf4\u660e\n\n1. **mode** (\u5b57\u7b26\u4e32): \u6570\u636e\u6a21\u5f0f\n   - `"summary"` \u6216 `"s"`: \u4ec5\u8fd4\u56de\u7edf\u8ba1\u6570\u636e\uff08\u63a8\u8350\uff1a\u6700\u7701 Token\uff09\n   - `"compact"` \u6216 `"c"`: \u8fd4\u56de\u7b80\u5316\u5b57\u6bb5\u7684\u8bb0\u5f55\u5217\u8868\uff08\u5e73\u8861\uff09\n   - `"full"` \u6216 `"f"`: \u8fd4\u56de\u5b8c\u6574\u6570\u636e\uff08\u9ed8\u8ba4\uff09\n\n2. **fields** (\u6570\u7ec4): \u76f4\u63a5\u6307\u5b9a\u8fd4\u56de\u5b57\u6bb5\uff08\u4f18\u5148\u7ea7\u9ad8\u4e8e mode\uff09\n   - \u793a\u4f8b: `fields: ["id", "title", "start", "end"]`\n   - \u53ea\u8fd4\u56de\u6307\u5b9a\u5b57\u6bb5\uff0c\u5176\u4ed6\u5b57\u6bb5\u5ffd\u7565\n\n#### \u4f7f\u7528\u5efa\u8bae\n\n'
o.a='\n## \ud83d\udcda \u5de5\u5177\u8be6\u7ec6\u6587\u6863\n\n### \u2699\ufe0f \u5b57\u6bb5\u8fc7\u6ee4\u673a\u5236\uff08\u51cf\u5c11 Token \u6d88\u8017\uff09\n\n**\u6240\u6709\u8fd4\u56de\u6570\u636e\u7684\u63d2\u4ef6\u65b9\u6cd5**\u90fd\u652f\u6301\u4ee5\u4e0b\u53ef\u9009\u53c2\u6570\u6765\u4f18\u5316\u8fd4\u56de\u7684\u6570\u636e\u91cf\uff1a\n\n#### \u53c2\u6570\u8bf4\u660e\n\n1. **mode** (\u5b57\u7b26\u4e32): \u6570\u636e\u6a21\u5f0f\n   - `"summary"` \u6216 `"s"`: \u4ec5\u8fd4\u56de\u7edf\u8ba1\u6570\u636e\uff08\u63a8\u8350\uff1a\u6700\u7701 Token\uff09\n   - `"compact"` \u6216 `"c"`: \u8fd4\u56de\u7b80\u5316\u5b57\u6bb5\u7684\u8bb0\u5f55\u5217\u8868\uff08\u5e73\u8861\uff09\n   - `"full"` \u6216 `"f"`: \u8fd4\u56de\u5b8c\u6574\u6570\u636e\uff08\u9ed8\u8ba4\uff09\n\n2. **fields** (\u6570\u7ec4): \u76f4\u63a5\u6307\u5b9a\u8fd4\u56de\u5b57\u6bb5\uff08\u4f18\u5148\u7ea7\u9ad8\u4e8e mode\uff09\n   - \u793a\u4f8b: `fields: ["id", "title", "start", "end"]`\n   - \u53ea\u8fd4\u56de\u6307\u5b9a\u5b57\u6bb5\uff0c\u5176\u4ed6\u5b57\u6bb5\u5ffd\u7565\n\n#### \u4f7f\u7528\u5efa\u8bae\n\n- \u5f53\u53ea\u9700\u8981\u7edf\u8ba1\u65f6\uff0c\u4f7f\u7528 `mode: "summary"`\n'
o.a='\n## \ud83d\udcda \u5de5\u5177\u8be6\u7ec6\u6587\u6863\n\n### \u2699\ufe0f \u5b57\u6bb5\u8fc7\u6ee4\u673a\u5236\uff08\u51cf\u5c11 Token \u6d88\u8017\uff09\n\n**\u6240\u6709\u8fd4\u56de\u6570\u636e\u7684\u63d2\u4ef6\u65b9\u6cd5**\u90fd\u652f\u6301\u4ee5\u4e0b\u53ef\u9009\u53c2\u6570\u6765\u4f18\u5316\u8fd4\u56de\u7684\u6570\u636e\u91cf\uff1a\n\n#### \u53c2\u6570\u8bf4\u660e\n\n1. **mode** (\u5b57\u7b26\u4e32): \u6570\u636e\u6a21\u5f0f\n   - `"summary"` \u6216 `"s"`: \u4ec5\u8fd4\u56de\u7edf\u8ba1\u6570\u636e\uff08\u63a8\u8350\uff1a\u6700\u7701 Token\uff09\n   - `"compact"` \u6216 `"c"`: \u8fd4\u56de\u7b80\u5316\u5b57\u6bb5\u7684\u8bb0\u5f55\u5217\u8868\uff08\u5e73\u8861\uff09\n   - `"full"` \u6216 `"f"`: \u8fd4\u56de\u5b8c\u6574\u6570\u636e\uff08\u9ed8\u8ba4\uff09\n\n2. **fields** (\u6570\u7ec4): \u76f4\u63a5\u6307\u5b9a\u8fd4\u56de\u5b57\u6bb5\uff08\u4f18\u5148\u7ea7\u9ad8\u4e8e mode\uff09\n   - \u793a\u4f8b: `fields: ["id", "title", "start", "end"]`\n   - \u53ea\u8fd4\u56de\u6307\u5b9a\u5b57\u6bb5\uff0c\u5176\u4ed6\u5b57\u6bb5\u5ffd\u7565\n\n#### \u4f7f\u7528\u5efa\u8bae\n\n- \u5f53\u53ea\u9700\u8981\u7edf\u8ba1\u65f6\uff0c\u4f7f\u7528 `mode: "summary"`\n- \u5f53\u9700\u8981\u5217\u8868\u4f46\u4e0d\u9700\u8981\u8be6\u7ec6\u63cf\u8ff0\u65f6\uff0c\u4f7f\u7528 `mode: "compact"`\n'
o.a=u.yN
n=u.yN+"- Token \u8282\u7701\u6bd4\u4f8b\uff1asummary(90%) > compact(75%) > full(0%)\n\n"
o.a=n
n+="#### \u4f7f\u7528\u793a\u4f8b\n\n"
o.a=n
n+="```javascript\n"
o.a=n
n+="// \u793a\u4f8b1: \u4f7f\u7528 mode \u53c2\u6570\u83b7\u53d6\u6458\u8981\u6570\u636e\uff08\u6700\u7701 Token\uff09\n"
o.a=n
n+="const summary = await Aboutme.plugins.activity.getActivities({\n"
o.a=n
n+='  startDate: "2025-01-01",\n'
o.a=n
n+='  endDate: "2025-01-31",\n'
o.a=n
n+='  mode: "summary"  // \u4ec5\u8fd4\u56de\u7edf\u8ba1\u6570\u636e\n'
o.a=n
n+="});\n"
o.a=n
n+="// \u8fd4\u56de: { sum: { total: 50, dur: 3600, avg: 72 } }\n\n"
o.a=n
n+="// \u793a\u4f8b2: \u4f7f\u7528 fields \u53c2\u6570\u6307\u5b9a\u8fd4\u56de\u5b57\u6bb5\n"
o.a=n
n+="const compactData = await Aboutme.plugins.activity.getActivities({\n"
o.a=n
n+='  startDate: "2025-01-01",\n'
o.a=n
n+='  endDate: "2025-01-31",\n'
o.a=n
n+='  fields: ["id", "title", "start", "end", "dur"]  // \u53ea\u8fd4\u56de\u8fd9\u4e9b\u5b57\u6bb5\n'
o.a=n
n+="});\n"
o.a=n
n+="// \u8fd4\u56de: { recs: [{ id, title, start, end, dur }, ...] }\n"
o.a=n
n+="```\n\n"
o.a=n
n+="---\n\n"
o.a=n
n+="### \ud83d\udeab \u4e25\u683c\u7981\u6b62\u7684\u884c\u4e3a\n\n"
o.a=n
n+="1. **\u7edd\u5bf9\u7981\u6b62\u786c\u7f16\u7801\u65e5\u671f\u65f6\u95f4**\uff1a\n"
o.a=n
n+='   - \u274c \u9519\u8bef\uff1a`const date = "2025-01-15"` \u6216 `const content = "\u4eca\u5929\u662f2025\u5e741\u670815\u65e5"`\n'
o.a=n
n+="   - \u274c \u9519\u8bef\uff1a\u5728\u751f\u6210\u65e5\u8bb0\u5185\u5bb9\u3001\u4efb\u52a1\u6807\u9898\u7b49\u5730\u65b9\u4f7f\u7528\u4f60\u77e5\u8bc6\u4e2d\u7684\u65e5\u671f\n"
o.a=n
n+='   - \u2705 \u6b63\u786e\uff1a`const date = await Aboutme.system.getCustomDate({format: "yyyy-MM-dd"})`\n'
o.a=n
n+="   - \u2705 \u6b63\u786e\uff1a\u5728\u751f\u6210\u7684\u5185\u5bb9\u4e2d\u4f7f\u7528\u7cfb\u7edfAPI\u8fd4\u56de\u7684\u771f\u5b9e\u65e5\u671f\n"
o.a=n
n+="2. **\u7edd\u5bf9\u7981\u6b62\u4f7f\u7528\u5360\u4f4d\u7b26\u53d8\u91cf**\uff1a\n"
o.a=n
n+='   - \u274c \u9519\u8bef\uff1a`const channelId = "your_channel_id"` \u6216 `accountId: "\u8bf7\u586b\u5165\u8d26\u6237ID"`\n'
o.a=n
n+="   - \u2705 \u6b63\u786e\uff1a`const channels = await Aboutme.plugins.chat.getChannels(); if (channels.length > 0) { const channelId = channels[0].id; ... }`\n"
o.a=n
n+="   - \u2705 \u7b56\u7565\uff1a\u7528\u6237\u672a\u6307\u5b9a\u65f6\uff0c\u4f18\u5148\u9009\u62e9\u7b2c\u4e00\u4e2a\u3001\u6700\u8fd1\u7684\u3001\u6216\u7b26\u5408\u6761\u4ef6\u7684\u6570\u636e\n"
o.a=n
n+="   - \u2705 \u7b56\u7565\uff1a\u5982\u679c\u6ca1\u6709\u53ef\u7528\u6570\u636e\uff0c\u5148\u521b\u5efa\u6570\u636e\u518d\u6267\u884c\u64cd\u4f5c\uff0c\u6216\u8fd4\u56de\u660e\u786e\u9519\u8bef\n\n"
o.a=n
n+="### \u7cfb\u7edf API\uff08\u59cb\u7ec8\u53ef\u7528\uff09\n\n"
o.a=n
n+="\u5728\u751f\u6210\u7684 JavaScript \u4ee3\u7801\u4e2d\uff0c\u4f60**\u5fc5\u987b\u4f7f\u7528**\u4ee5\u4e0b\u7cfb\u7edf API \u83b7\u53d6\u65f6\u95f4\u4fe1\u606f\uff1a\n\n"
o.a=n
n+="- `await Aboutme.system.getCustomDate(options)` - **\u63a8\u8350\u4f7f\u7528\uff0c\u89e3\u51b3\u65f6\u533a\u95ee\u9898**\n"
o.a=n
n+="  - options: `{baseDate?, timezone?, add?, subtract?, relativePosition?, format?}`\n"
o.a=n
n+='  - relativePosition: "startOfDay"\u3001"endOfDay"\u3001"startOfWeek"\u3001"startOfMonth" \u7b49\n'
o.a=n
n+='  - format: "object"\u3001"timestamp"\u3001"iso"\u3001"text" \u6216\u81ea\u5b9a\u4e49\u683c\u5f0f\u5982 "yyyy-MM-dd"\n'
o.a=n
n+='  - \u793a\u4f8b\uff1a`await Aboutme.system.getCustomDate({relativePosition: "startOfDay", format: "timestamp"})`\n'
o.a=n
n+="- `await Aboutme.system.getCurrentTime()` - \u83b7\u53d6\u5f53\u524d\u65f6\u95f4\n"
o.a=n
n+="  - \u8fd4\u56de\uff1a`{ timestamp, datetime, year, month, day, hour, minute, second, weekday, weekdayName }`\n"
o.a=n
n+=u.vW
o.a=n
n+=u.po
o.a=n
n+="  - dateInput: \u65f6\u95f4\u6233\uff08\u6beb\u79d2\uff09\u6216 ISO \u5b57\u7b26\u4e32\n"
o.a=n
n+='  - format: \u683c\u5f0f\u6a21\u677f\uff0c\u5982 "yyyy-MM-dd HH:mm:ss"\n'
o.a=n
n+=u.eZ
o.a=n
n+="- `await Aboutme.system.getAppInfo()` - \u83b7\u53d6\u5e94\u7528\u4fe1\u606f\n\n"
o.a=n
n+="\u26a0\ufe0f **\u91cd\u8981**\uff1a\u4e0d\u8981\u5c06\u7cfb\u7edf API \u4f5c\u4e3a\u5355\u72ec\u7684\u6b65\u9aa4\uff0c\u800c\u662f\u5728\u9700\u8981\u65f6\u76f4\u63a5\u5728\u4ee3\u7801\u4e2d\u8c03\u7528\uff01\n\n"
o.a=n
n+="### \u6b65\u9aa4\u95f4\u7ed3\u679c\u4f20\u9012 API\uff08\u591a\u6b65\u9aa4\u6570\u636e\u5171\u4eab\uff09\n\n"
o.a=n
n+="\u5f53\u9700\u8981\u5728\u591a\u4e2a\u6b65\u9aa4\u4e4b\u95f4\u4f20\u9012\u6570\u636e\u65f6\uff0c\u4f7f\u7528\u4ee5\u4e0b API\uff1a\n\n"
o.a=n
n+="#### \u26a0\ufe0f \u5f3a\u5236\u8981\u6c42\uff1a\u5fc5\u987b\u4f7f\u7528\u5bf9\u8c61\u7c7b\u578b\n\n"
o.a=n
n+=u.eu
o.a=n
n+=u.n6
o.a=n
n+="**\u8bbe\u7f6e\u7ed3\u679c**\uff1a\n"
o.a=n
n+="```javascript\n"
o.a=n
n+="await Aboutme.toolCall.setResult({\n"
o.a=n
n+='  id: "myData",    // \u53ef\u9009\uff1a\u81ea\u5b9a\u4e49 ID\n'
o.a=n
n+="  value: {data: dataObj}   // \u5fc5\u9700\uff1a\u5fc5\u987b\u662f\u5bf9\u8c61\uff0c\u7528\u5c5e\u6027\u5305\u88c5\u6570\u636e\n"
o.a=n
n+="});\n"
o.a=n
n+="```\n\n"
o.a=n
n+="**\u83b7\u53d6\u7ed3\u679c**\uff1a\n"
o.a=n
n+="```javascript\n"
o.a=n
n+="// \u65b9\u5f0f1: \u901a\u8fc7\u81ea\u5b9a\u4e49 ID\n"
o.a=n
n+='const result = await Aboutme.toolCall.getResult({id: "myData"});\n'
o.a=n
n+="const data = result.data; // \u901a\u8fc7\u5c5e\u6027\u8bbf\u95ee\n"
o.a=n
n+="\n"
o.a=n
n+="// \u65b9\u5f0f2: \u901a\u8fc7\u6b65\u9aa4\u7d22\u5f15\uff080 = \u7b2c\u4e00\u4e2a\u6b65\u9aa4\uff09\n"
